<?php
/**
 * TFP Abandoned Cart Email Template.
 *
 * Expected variables:
 * - $cart_items: array of ['product' => WC_Product, 'quantity' => int]
 * - $cart_url: secure cart-restoration URL generated by the abandoned-cart integration
 * - $customer_name: optional customer display name
 */
defined('ABSPATH') || exit;

$cart_items = isset($cart_items) && is_array($cart_items) ? $cart_items : [];
$cart_url = !empty($cart_url) ? $cart_url : '';
$cart_url = apply_filters('tfp_abandoned_cart_restore_url', $cart_url, $cart_items);
$customer_name = isset($customer_name) ? $customer_name : '';
$blogname = get_bloginfo('name');
$logo_url = defined('TFP_AUTH_URL') ? trailingslashit(TFP_AUTH_URL) . 'assets/images/MAIN_LOGO.png' : '';
$shop_url = function_exists('wc_get_page_permalink') ? wc_get_page_permalink('shop') : home_url('/shop/');
$view_url = apply_filters('tfp_abandoned_cart_view_url', home_url('/'));
$cart_product_ids = [];
foreach ($cart_items as $cart_item) {
    if (!empty($cart_item['product']) && $cart_item['product'] instanceof WC_Product) {
        $cart_product_ids[] = $cart_item['product']->get_id();
    }
}
$recommended_products = function_exists('wc_get_products') ? wc_get_products([
    'status' => 'publish',
    'limit' => 2,
    'exclude' => $cart_product_ids,
    'category' => ['books'],
    'orderby' => 'date',
    'order' => 'DESC',
]) : [];
?>
<style type="text/css">
@media only screen and (max-width:620px) {
    .tfp-ac-shell { width:100% !important; max-width:100% !important; }
    .tfp-ac-pad { padding-left:20px !important; padding-right:20px !important; }
    .tfp-ac-title { font-size:28px !important; line-height:35px !important; }
    .tfp-ac-product-image { width:76px !important; height:90px !important; }
    .tfp-ac-product-name { font-size:14px !important; }
    .tfp-ac-recommend-image { width:100% !important; height:auto !important; }
    .tfp-ac-recommend-col { display:block !important; width:100% !important; padding:0 0 24px !important; }
    .tfp-ac-social { padding-left:20px !important; padding-right:20px !important; }
}
</style>
<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="margin:0;padding:0;background:#fff;">
<tr><td align="center" style="padding:4px;background:#f5f5f5;">
