<tr><td style="height:42px;background:#00666e;padding:0 24px;text-align:right;font:700 12px/16px Arial,sans-serif;color:#fff;"><a href="<?php echo esc_url($view_url); ?>" style="color:#fff;text-decoration:none;">View in browser →</a></td></tr>
