<?php if ($logo_url): ?><a href="<?php echo esc_url(home_url('/')); ?>"><img src="<?php echo esc_url($logo_url); ?>" alt="<?php echo esc_attr($blogname); ?>" width="212" style="display:block;width:212px;max-width:100%;height:auto;margin:0 auto 22px;border:0;"></a><?php endif; ?>
<table role="presentation" cellpadding="0" cellspacing="0" border="0" align="center"><tr>
<td style="padding:0 24px;font:18px/24px Arial,sans-serif;"><a href="<?php echo esc_url($shop_url); ?>" style="color:#1c1b1b;text-decoration:none;">Shop</a></td>
<td style="padding:0 24px;font:18px/24px Arial,sans-serif;"><a href="<?php echo esc_url(home_url('/about-us/')); ?>" style="color:#1c1b1b;text-decoration:none;">About Us</a></td>
<td style="padding:0 24px;font:18px/24px Arial,sans-serif;"><a href="<?php echo esc_url(home_url('/updates/')); ?>" style="color:#1c1b1b;text-decoration:none;">Updates</a></td>
<td style="padding:0 24px;font:18px/24px Arial,sans-serif;"><a href="<?php echo esc_url(home_url('/contact/')); ?>" style="color:#1c1b1b;text-decoration:none;">Contacts</a></td>
</tr></table>
</td></tr>
<tr><td align="center" class="tfp-ac-pad" style="padding:38px 40px 52px;text-align:center;">
<div style="font:700 16px/22px Arial,sans-serif;color:#c69a00;">You Left Something Behind</div>
<h1 class="tfp-ac-title" style="margin:10px 0 12px;font:700 30px/38px Arial,sans-serif;color:#171717;">Still deciding?</h1>
<p style="margin:0;font:italic 16px/24px Georgia,serif;color:#252525;">Your book is still waiting for you.</p>
<?php if ($customer_name): ?><p style="margin:10px 0 0;font:14px/22px Georgia,serif;color:#252525;"><?php echo esc_html(sprintf(__('Hi %s, your cart is saved for you.', 'tfp-authentication'), $customer_name)); ?></p><?php endif; ?>
<?php if ($cart_url): ?><table role="presentation" cellpadding="0" cellspacing="0" border="0" align="center" style="margin:24px auto 0;"><tr><td align="center" bgcolor="#00666e" style="border-radius:8px;"><a href="<?php echo esc_url($cart_url); ?>" style="display:inline-block;padding:16px 32px;font:700 16px/20px Arial,sans-serif;color:#fff;text-decoration:none;border-radius:8px;">Return to Your Cart →</a></td></tr></table><?php else: ?><p style="margin:20px 0 0;font:12px/18px Arial,sans-serif;color:#9a3333;">Cart restoration link will be added by the abandoned-cart integration.</p><?php endif; ?>
</td></tr>
<tr><td class="tfp-ac-pad" style="padding:0 40px 44px;">
<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%"><tr><td style="border-top:2px solid #b47c7c;font-size:1px;line-height:1px;">&nbsp;</td></tr></table>
<?php if ($cart_items): ?>
<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="margin-top:28px;">
<?php foreach ($cart_items as $cart_item):
    $product = $cart_item['product'] ?? null;
    if (!$product instanceof WC_Product) { continue; }
    $quantity = max(1, absint($cart_item['quantity'] ?? 1));
    $image_id = $product->get_image_id();
    $image_url = $image_id ? wp_get_attachment_image_url($image_id, 'woocommerce_thumbnail') : wc_placeholder_img_src();
    $line_price = (float) wc_get_price_to_display($product) * $quantity;
?>
<tr><td style="padding:0 0 14px;border-bottom:1px solid #dedede;">
<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%"><tr>
<td width="90" valign="middle" style="width:90px;padding:0 22px 0 0;"><img class="tfp-ac-product-image" src="<?php echo esc_url($image_url); ?>" alt="<?php echo esc_attr($product->get_name()); ?>" width="90" height="90" style="display:block;width:90px;height:90px;object-fit:cover;border:0;"></td>
<td valign="middle" style="font-family:Arial,sans-serif;"><div class="tfp-ac-product-name" style="font-size:14px;line-height:20px;font-weight:700;color:#171717;"><?php echo esc_html($product->get_name()); ?></div><div style="padding-top:6px;font:12px/18px Georgia,serif;color:#252525;"><?php echo esc_html(wp_trim_words($product->get_short_description() ?: $product->get_name(), 9)); ?></div><div style="padding-top:6px;font:10px/14px Arial,sans-serif;color:#9c9ca4;"><?php echo esc_html(sprintf(__('Qty: %d', 'tfp-authentication'), $quantity)); ?></div></td>
<td width="86" align="right" valign="middle" style="width:86px;font:700 14px/20px Arial,sans-serif;color:#171717;"><?php echo wp_kses_post(wc_price($line_price)); ?></td>
</tr></table>
</td></tr>
<?php endforeach; ?>
</table>
<?php else: ?>
<p style="margin:28px 0;font:14px/22px Arial,sans-serif;color:#555;text-align:center;">Your saved cart items will appear here.</p>
<?php endif; ?>
</td></tr>
<?php if ($recommended_products): ?>
<tr><td class="tfp-ac-pad" style="padding:0 40px 40px;">
<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%"><tr><td style="border-top:2px solid #b47c7c;font-size:1px;line-height:1px;">&nbsp;</td></tr></table>
