<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%"><tr>
<?php foreach ($recommended_products as $recommended): if (!$recommended instanceof WC_Product) { continue; }
    $rec_image_id = $recommended->get_image_id();
    $rec_image = $rec_image_id ? wp_get_attachment_image_url($rec_image_id, 'woocommerce_thumbnail') : wc_placeholder_img_src();
?>
<td class="tfp-ac-recommend-col" width="50%" valign="top" align="center" style="width:50%;padding:0 10px;">
<a href="<?php echo esc_url($recommended->get_permalink()); ?>" style="text-decoration:none;"><img class="tfp-ac-recommend-image" src="<?php echo esc_url($rec_image); ?>" alt="<?php echo esc_attr($recommended->get_name()); ?>" width="250" height="220" style="display:block;width:100%;height:220px;object-fit:cover;border:0;background:#d8c7a8;"></a>
<div style="padding-top:12px;font:700 16px/21px Arial,sans-serif;color:#171717;"><?php echo esc_html($recommended->get_name()); ?></div>
<div style="font:12px/18px Georgia,serif;color:#252525;"><?php echo esc_html(wp_trim_words($recommended->get_short_description(), 8)); ?></div>
<table role="presentation" cellpadding="0" cellspacing="0" border="0" align="center" style="margin:12px auto 0;"><tr><td bgcolor="#00666e" style="border-radius:8px;"><a href="<?php echo esc_url($recommended->get_permalink()); ?>" style="display:inline-block;padding:9px 20px;font:14px/18px Arial,sans-serif;color:#fff;text-decoration:none;border-radius:8px;">Shop Now →</a></td></tr></table>
</td>
<?php endforeach; ?>
</tr></table>
